	"Light recipe": { nl: "Lichtschema", de: "Lichtrezept" },
	"A researched lighting schedule matched to the birds' biology to support welfare.": { nl: "Een onderzocht lichtschema afgestemd op de biologie van de dieren om het welzijn te ondersteunen.", de: "Ein erforschtes Lichtprogramm, abgestimmt auf die Biologie der Tiere, um das Tierwohl zu fördern." },
	"Bioenergy plant — green gas production": { nl: "Bio-energiecentrale — groengasproductie", de: "Bioenergieanlage — Grüngasproduktion" },
	"Green gas": { nl: "Groen gas", de: "Grünes Gas" },
	"Upgrades biogas to grid-quality green gas, turning manure streams into renewable energy.": { nl: "Waardeert biogas op tot groen gas van netkwaliteit en zet meststromen om in hernieuwbare energie.", de: "Bereitet Biogas zu Grüngas in Netzqualität auf und macht aus Gülleströmen erneuerbare Energie." },
	"Air scrubber": { nl: "Luchtwasser", de: "Abluftwäscher" },
