	"Water treatment that keeps drinking lines clean and cuts contaminated discharge.": { nl: "Waterbehandeling die drinkwaterleidingen schoon houdt en verontreinigde lozing vermindert.", de: "Wasseraufbereitung, die Tränkeleitungen sauber hält und kontaminierte Abwässer reduziert." },
	"Fire-suppression technology": { nl: "Brandblustechnologie", de: "Brandbekämpfungstechnologie" },
