	"Bioenergy plant — N₂ stripper (digestate)": { nl: "Bio-energiecentrale — N₂-stripper (digestaat)", de: "Bioenergieanlage — N₂-Stripper (Gärrest)" },
	"N₂ stripper": { nl: "N₂-stripper", de: "N₂-Stripper" },
